import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Object3D,
  TextureLoader
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const {
    scenePlacement,
    behavior,
    assets,
    cinematicPrimitives
  } = config;

  // Create geometry and material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    map: ctx.textureLoader.load(assets.imageUrl)
  });

  // Create mesh
  const mesh = new Mesh(geometry, material);
  mesh.position.set(scenePlacement.position.x, scenePlacement.position.y, scenePlacement.position.z);
  mesh.rotation.set(scenePlacement.rotation.x, scenePlacement.rotation.y, scenePlacement.rotation.z);
  mesh.scale.set(scenePlacement.scale.x, scenePlacement.scale.y, scenePlacement.scale.z);

  // Make interactive
  mesh.userData.interactive = true;

  // --- Event Handlers ---
  const handlers = {};

  // Hover: rise-in preset (subtle, 0.15 units)
  let hoverTimeline = null;
  handlers.hoverStart = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };
  handlers.hoverEnd = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(mesh.position, {
      y: mesh.position.y,
      duration: 0.5,
      ease: 'power2.out'
    });
  };

  // Click: emit hub-journal.select
  handlers.click = () => {
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('hub-journal.select', { detail: { source: 'quote-panel' } }));
    }
  };

  mesh.userData.handlers = handlers;

  // --- Apply Cinematic Primitives ---
  if (ctx.primitives && cinematicPrimitives) {
    cinematicPrimitives.forEach(prim => {
      if (ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](mesh, prim.params);
      }
    });
  }

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    if (hoverTimeline) hoverTimeline.kill();
  };

  return mesh;
}
